Your part:

```python
_TRUE = {"true", "pass", "passed", "1", "yes"}
_FALSE = {"false", "fail", "failed", "0", "no"}


def _to_bool(value):
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)) and value in (0, 1):
        return bool(value)
    if isinstance(value, str):
        v = value.strip().lower()
        if v in _TRUE:
            return True
        if v in _FALSE:
            return False
    return None


def _to_latency(value):
    if value is None or isinstance(value, bool):
        return None
    try:
        ms = float(value)
    except (TypeError, ValueError):
        return None
    return ms if math.isfinite(ms) and ms >= 0 else None


def parse_records(lines) -> tuple[list[dict], int]:
    if isinstance(lines, str):
        lines = lines.splitlines()
    records, bad = [], 0
    for line in lines:
        if not line.strip():
            continue
        try:
            row = json.loads(line)
        except json.JSONDecodeError:
            bad += 1
            continue
        if not isinstance(row, dict):
            bad += 1
            continue
        model, task = row.get("model"), row.get("task")
        passed = _to_bool(row.get("passed"))
        if not isinstance(model, str) or not model.strip() or not isinstance(task, str) \
                or not task.strip() or passed is None:
            bad += 1
            continue
        records.append({"model": model.strip(), "task": task.strip(), "passed": passed,
                        "latency_ms": _to_latency(row.get("latency_ms"))})
    return records, bad


def pass_rates(records: list[dict], by: tuple[str, ...] = ("model",)) -> dict[tuple, dict]:
    counts = defaultdict(lambda: [0, 0])
    for r in records:
        key = tuple(r[f] for f in by)
        counts[key][0] += 1
        counts[key][1] += int(r["passed"])
    return {k: {"n": n, "pass_rate": p / n} for k, (n, p) in counts.items()}


def latency_percentiles(records: list[dict], by: str = "model") -> dict[str, dict]:
    groups = defaultdict(list)
    for r in records:
        if r["latency_ms"] is not None:
            groups[r[by]].append(r["latency_ms"])
    out = {}
    for key, values in groups.items():
        p50, p95 = np.percentile(np.asarray(values, float), [50, 95])
        out[key] = {"p50": float(p50), "p95": float(p95)}
    return out
```
